begin;
drop policy if exists shifts_staff_insert on public.shifts;
drop policy if exists shifts_staff_update on public.shifts;
drop policy if exists handover_records_staff_insert on public.handover_records;
drop policy if exists handover_records_staff_update on public.handover_records;
drop policy if exists notification_tasks_staff_insert on public.notification_tasks;
drop policy if exists notification_tasks_staff_update on public.notification_tasks;
alter table public.shifts add constraint shifts_no_staff_overlap exclude using gist(organization_id with =,staff_user_id with =,tstzrange(starts_at,ends_at,'[)') with &&) where(status<>'cancelled');

create or replace function public.list_staff(p_organization_id uuid) returns table(user_id uuid,display_name text,role text,status text) language sql stable security definer set search_path=public,pg_temp as $$
 select m.user_id,p.display_name,m.role,m.status from public.organization_members m join public.profiles p on p.id=m.user_id where m.organization_id=p_organization_id and public.current_user_has_org(p_organization_id,array['owner','manager','staff']) and m.role in('owner','manager','staff') order by p.display_name
$$;
revoke all on function public.list_staff(uuid) from public;grant execute on function public.list_staff(uuid) to authenticated;

create or replace function public.schedule_shift(p_organization_id uuid,p_staff_user_id uuid,p_starts_at timestamptz,p_ends_at timestamptz) returns public.shifts language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.shifts%rowtype;begin if not public.current_user_has_org(p_organization_id,array['owner','manager']) then raise exception 'permission denied';end if;if p_ends_at<=p_starts_at then raise exception 'shift end must be after start';end if;if not exists(select 1 from public.organization_members where organization_id=p_organization_id and user_id=p_staff_user_id and status='active' and role in('owner','manager','staff')) then raise exception 'active staff not found';end if;insert into public.shifts(organization_id,staff_user_id,starts_at,ends_at,created_by,updated_by) values(p_organization_id,p_staff_user_id,p_starts_at,p_ends_at,auth.uid(),auth.uid()) returning * into v;return v;end $$;
revoke all on function public.schedule_shift(uuid,uuid,timestamptz,timestamptz) from public;grant execute on function public.schedule_shift(uuid,uuid,timestamptz,timestamptz) to authenticated;

create or replace function public.start_shift(p_shift_id uuid,p_expected_version integer) returns public.shifts language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.shifts%rowtype;begin select * into v from public.shifts where id=p_shift_id for update;if not found or not public.current_user_has_org(v.organization_id,array['owner','manager','staff']) or (v.staff_user_id<>auth.uid() and public.current_org_role(v.organization_id)='staff') then raise exception 'shift not found';end if;if v.version<>p_expected_version then raise exception 'shift changed; reload' using errcode='40001';end if;if v.status<>'scheduled' then raise exception 'shift cannot be started';end if;update public.shifts set status='active',actual_start_at=now(),updated_by=auth.uid() where id=v.id returning * into v;return v;end $$;
revoke all on function public.start_shift(uuid,integer) from public;grant execute on function public.start_shift(uuid,integer) to authenticated;

create or replace function public.shift_summary(p_shift_id uuid) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare v public.shifts%rowtype;begin select * into v from public.shifts where id=p_shift_id;if not found or not public.current_user_has_org(v.organization_id,array['owner','manager','staff']) then raise exception 'shift not found';end if;return jsonb_build_object(
 'pending_tasks',(select count(*) from public.tasks where organization_id=v.organization_id and status in('pending','in_progress','requires_confirmation') and (assigned_to is null or assigned_to=v.staff_user_id)),
 'pending_medications',(select count(*) from public.medication_records where organization_id=v.organization_id and status in('pending','in_progress','requires_confirmation')),
 'unresolved_events',(select count(*) from public.abnormal_events where organization_id=v.organization_id and status in('open','monitoring')),
 'pending_notifications',(select count(*) from public.notification_tasks where organization_id=v.organization_id and status in('pending','message_copied','waiting_response')),
 'pending_cleaning',(select count(*) from public.cleaning_records where organization_id=v.organization_id and status<>'completed'),
 'unacknowledged_handovers',(select count(*) from public.handover_records where organization_id=v.organization_id and important and acknowledged_at is null and (to_user_id is null or to_user_id=v.staff_user_id)));
end $$;
revoke all on function public.shift_summary(uuid) from public;grant execute on function public.shift_summary(uuid) to authenticated;

create or replace function public.create_handover(p_from_shift_id uuid,p_to_user_id uuid,p_reservation_id uuid,p_important boolean,p_notes text) returns public.handover_records language plpgsql security definer set search_path=public,pg_temp as $$
declare v_shift public.shifts%rowtype;v public.handover_records%rowtype;begin select * into v_shift from public.shifts where id=p_from_shift_id;if not found or not public.current_user_has_org(v_shift.organization_id,array['owner','manager','staff']) or (public.current_org_role(v_shift.organization_id)='staff' and v_shift.staff_user_id<>auth.uid()) then raise exception 'shift not found';end if;if length(trim(coalesce(p_notes,'')))<2 then raise exception 'handover notes are required';end if;if p_to_user_id is not null and not exists(select 1 from public.organization_members where organization_id=v_shift.organization_id and user_id=p_to_user_id and status='active' and role in('owner','manager','staff')) then raise exception 'receiving staff not found';end if;if p_reservation_id is not null and not exists(select 1 from public.reservations where organization_id=v_shift.organization_id and id=p_reservation_id) then raise exception 'reservation not found';end if;insert into public.handover_records(organization_id,from_shift_id,to_user_id,reservation_id,important,notes,created_by,updated_by) values(v_shift.organization_id,v_shift.id,p_to_user_id,p_reservation_id,coalesce(p_important,false),trim(p_notes),auth.uid(),auth.uid()) returning * into v;return v;end $$;
revoke all on function public.create_handover(uuid,uuid,uuid,boolean,text) from public;grant execute on function public.create_handover(uuid,uuid,uuid,boolean,text) to authenticated;

create or replace function public.acknowledge_handover(p_handover_id uuid,p_expected_version integer) returns public.handover_records language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.handover_records%rowtype;begin select * into v from public.handover_records where id=p_handover_id for update;if not found or not public.current_user_has_org(v.organization_id,array['owner','manager','staff']) then raise exception 'handover not found';end if;if v.version<>p_expected_version then raise exception 'handover changed; reload' using errcode='40001';end if;if v.to_user_id is not null and v.to_user_id<>auth.uid() and public.current_org_role(v.organization_id)='staff' then raise exception 'only assigned receiving staff may acknowledge';end if;if v.acknowledged_at is not null then return v;end if;update public.handover_records set acknowledged_by=auth.uid(),acknowledged_at=now(),updated_by=auth.uid() where id=v.id returning * into v;return v;end $$;
revoke all on function public.acknowledge_handover(uuid,integer) from public;grant execute on function public.acknowledge_handover(uuid,integer) to authenticated;

create or replace function public.complete_shift(p_shift_id uuid,p_expected_version integer,p_exception text default null) returns public.shifts language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.shifts%rowtype;v_pending integer;begin select * into v from public.shifts where id=p_shift_id for update;if not found or not public.current_user_has_org(v.organization_id,array['owner','manager','staff']) or (v.staff_user_id<>auth.uid() and public.current_org_role(v.organization_id)='staff') then raise exception 'shift not found';end if;if v.version<>p_expected_version then raise exception 'shift changed; reload' using errcode='40001';end if;if v.status not in('active','handover_required') then raise exception 'shift cannot be completed';end if;select count(*) into v_pending from public.tasks where organization_id=v.organization_id and status in('pending','in_progress','requires_confirmation') and (assigned_to is null or assigned_to=v.staff_user_id);if v_pending>0 and length(trim(coalesce(p_exception,'')))<3 then raise exception 'pending work requires handover or documented exception';end if;if exists(select 1 from public.handover_records where organization_id=v.organization_id and from_shift_id=v.id and important and acknowledged_at is null) then raise exception 'important handover is not acknowledged';end if;update public.shifts set status='completed',actual_end_at=now(),completion_exception=nullif(trim(p_exception),''),updated_by=auth.uid() where id=v.id returning * into v;return v;end $$;
revoke all on function public.complete_shift(uuid,integer,text) from public;grant execute on function public.complete_shift(uuid,integer,text) to authenticated;

create or replace function public.transition_notification(p_notification_id uuid,p_to_status text,p_channel text default null,p_response text default null,p_notes text default null,p_expected_version integer default null) returns public.notification_tasks language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.notification_tasks%rowtype;v_from text;begin select * into v from public.notification_tasks where id=p_notification_id for update;if not found or not public.current_user_has_org(v.organization_id,array['owner','manager','staff']) then raise exception 'notification not found';end if;if p_expected_version is not null and v.version<>p_expected_version then raise exception 'notification changed; reload' using errcode='40001';end if;if p_to_status not in('pending','message_copied','sent','waiting_response','confirmed','rescheduled','not_required','cancelled') then raise exception 'invalid notification status';end if;v_from=v.status;if not((v_from='pending' and p_to_status in('message_copied','sent','rescheduled','not_required','cancelled')) or (v_from='message_copied' and p_to_status in('pending','sent','rescheduled','not_required','cancelled')) or (v_from='sent' and p_to_status in('waiting_response','confirmed','rescheduled')) or (v_from='waiting_response' and p_to_status in('sent','confirmed','rescheduled')) or (v_from='rescheduled' and p_to_status in('pending','message_copied','sent','cancelled')) or v_from=p_to_status) then raise exception 'invalid notification transition';end if;if p_to_status='sent' and length(trim(coalesce(p_channel,'')))<2 then raise exception 'sent notification requires channel';end if;update public.notification_tasks set status=p_to_status,actual_notified_at=case when p_to_status='sent' then now() else actual_notified_at end,responsible_staff=auth.uid(),channel=coalesce(nullif(trim(p_channel),''),channel),response=coalesce(nullif(trim(p_response),''),response),notes=coalesce(nullif(trim(p_notes),''),notes),updated_by=auth.uid() where id=v.id returning * into v;insert into public.notification_logs(organization_id,notification_task_id,action,from_status,to_status,details,created_by) values(v.organization_id,v.id,'status_transition',v_from,p_to_status,jsonb_build_object('channel',p_channel,'response',p_response,'notes',p_notes),auth.uid());return v;end $$;
revoke all on function public.transition_notification(uuid,text,text,text,text,integer) from public;grant execute on function public.transition_notification(uuid,text,text,text,text,integer) to authenticated;

create or replace function public.guard_checkout_item_check() returns trigger language plpgsql set search_path=public,pg_temp as $$
begin
 if tg_op='INSERT' then new.created_by=auth.uid();end if;new.updated_by=auth.uid();
 if new.status<>'pending' and (tg_op='INSERT' or old.status is distinct from new.status) then new.verified_by=auth.uid();new.verified_at=now();end if;
 if new.status='pending' then new.verified_by=null;new.verified_at=null;end if;return new;
end $$;
create trigger checkout_item_checks_identity before insert or update on public.checkout_item_checks for each row execute function public.guard_checkout_item_check();

create or replace function public.guard_cleaning_completion() returns trigger language plpgsql set search_path=public,pg_temp as $$
begin if new.status='completed' and old.status<>'completed' then if not(coalesce((new.checklist->>'litter_box')::boolean,false) and coalesce((new.checklist->>'bowls')::boolean,false) and coalesce((new.checklist->>'bedding')::boolean,false) and coalesce((new.checklist->>'disinfection')::boolean,false)) then raise exception 'required cleaning checklist is incomplete';end if;new.completed_at=now();new.responsible_staff=auth.uid();end if;return new;end $$;
create trigger cleaning_records_completion_guard before update on public.cleaning_records for each row execute function public.guard_cleaning_completion();
commit;
